//! What the C run-time's startup gives an MSVC program: the entry point, the initializers
//! of C and C++ code, and the TLS directory.

use core::ffi::c_void;
use core::ptr;

use crate::sys;

extern "C" {
    /// Generated by rustc for a program's `fn main` (it calls std's `lang_start`).
    fn main(argc: i32, argv: *const *const u8) -> i32;
}

/// The entry point the linker gives a console or GUI program: it runs the initializers of
/// C and C++ code linked in (see below), then `main`. std takes the command line from
/// `GetCommandLineW`, so `main` gets no arguments; its result is the exit code.
#[no_mangle]
pub unsafe extern "C" fn mainCRTStartup() -> ! {
    // SAFETY: the tables hold the initializers the compiler put there, or nothing; main is
    // rustc's entry; ExitProcess does not return.
    unsafe {
        run_initializers();
        sys::ExitProcess(main(0, ptr::null()) as u32)
    }
}

// The initializer tables of the Microsoft C run-time, which C and C++ code compiled with
// Microsoft C fill: a C initializer (returning non-zero on failure) goes in a .CRT$XI?
// section, a C++ constructor or an initializer of C code (GnuTLS's library constructor) in
// a .CRT$XC? one. The linker sorts the sections by the letter after the $, so the tables
// run from the entries of XIA/XCA to those of XIZ/XCZ, which are ours.
type CInit = Option<unsafe extern "C" fn() -> i32>;
type CppInit = Option<unsafe extern "C" fn()>;

#[link_section = ".CRT$XIA"]
#[used]
static XI_A: CInit = None;
#[link_section = ".CRT$XIZ"]
#[used]
static XI_Z: CInit = None;
#[link_section = ".CRT$XCA"]
#[used]
static XC_A: CppInit = None;
#[link_section = ".CRT$XCZ"]
#[used]
static XC_Z: CppInit = None;

unsafe fn run_initializers() {
    // SAFETY: the entries between the markers are function pointers or null (padding).
    unsafe {
        let mut p = (&raw const XI_A).wrapping_add(1);
        while p < &raw const XI_Z {
            if let Some(f) = ptr::read_volatile(p) {
                if f() != 0 {
                    sys::ExitProcess(255);
                }
            }
            p = p.wrapping_add(1);
        }
        let mut p = (&raw const XC_A).wrapping_add(1);
        while p < &raw const XC_Z {
            if let Some(f) = ptr::read_volatile(p) {
                f();
            }
            p = p.wrapping_add(1);
        }
    }
}

/// A TLS callback: `(module, reason, reserved)`.
type TlsCallback = unsafe extern "system" fn(*mut c_void, u32, *mut c_void);

/// The TLS directory of the image (IMAGE_TLS_DIRECTORY), which the linker points the
/// image's TLS entry at when it finds `_tls_used`. NT 4.0's loader then calls the callbacks
/// listed between `.CRT$XLA` and `.CRT$XLZ` when a thread starts and ends; std puts its
/// own in `.CRT$XLB` to run the destructors of its thread-locals. The TLS data template runs
/// from `.tls` to `.tls$ZZZ`: the thread-locals of C code linked in (Rust's on this target
/// are not `#[thread_local]`), which the linker puts in between.
#[repr(C)]
pub struct TlsDirectory {
    start_of_raw_data: *const u8,
    end_of_raw_data: *const u8,
    address_of_index: *const u32,
    address_of_callbacks: *const Option<TlsCallback>,
    size_of_zero_fill: u32,
    characteristics: u32,
}

// SAFETY: read-only, read by the loader.
unsafe impl Sync for TlsDirectory {}

// Writable, like the .tls sections Microsoft C emits for C code's thread-locals: the
// linker merges sections of one name only when their flags agree, and the template must
// be one section from TLS_START to TLS_END.
#[link_section = ".tls"]
#[used]
static mut TLS_START: u8 = 0;

#[link_section = ".tls$ZZZ"]
#[used]
static mut TLS_END: u8 = 0;

/// The image's TLS index, which the loader fills in: what C code's thread-locals
/// (`_Thread_local`, `__declspec(thread)`) are reached through, by this name.
// On x86, LLVM's C prefix makes it __tls_index, as the linker expects.
#[export_name = "_tls_index"]
#[used]
static mut TLS_INDEX: u32 = 0;

#[link_section = ".CRT$XLA"]
#[used]
static XL_A: Option<TlsCallback> = None;

#[link_section = ".CRT$XLZ"]
#[used]
static XL_Z: Option<TlsCallback> = None;

#[export_name = "_tls_used"]
#[used]
pub static TLS_USED: TlsDirectory = TlsDirectory {
    start_of_raw_data: &raw const TLS_START,
    end_of_raw_data: &raw const TLS_END,
    address_of_index: &raw const TLS_INDEX,
    // The callbacks start after XL_A's empty slot; XL_Z's ends the list.
    address_of_callbacks: (&raw const XL_A).wrapping_add(1),
    size_of_zero_fill: 0,
    characteristics: 0,
};
